<?php
if(!defined('ABSPATH'))exit;
add_action('admin_menu',function(){add_menu_page('Pelham Applications','Pelham Applications','pelham_review_applications','pelham-applications','pa_admin','dashicons-clipboard',27);});
add_action('admin_enqueue_scripts',function($hook){if($hook!=='toplevel_page_pelham-applications')return;wp_enqueue_style('pa-admin',plugins_url('../assets/admin.css',__FILE__),[],PA_VERSION);wp_enqueue_script('pa-admin',plugins_url('../assets/admin.js',__FILE__),[],PA_VERSION,true);});
function pa_admin(){
 if(!pa_can_review())wp_die('Not authorized.',403);
 echo '<div class="wrap pa-admin"><header class="pa-dashboard-heading"><span class="pa-kicker">PELHAM · SALES DESK</span><h1>Applications &amp; claims</h1><p>Review customer documents, check signatures and prepare the next conversation.</p></header>';
 if(!has_filter('pelham_scan_attachment'))echo '<div class="notice notice-warning"><p>No attachment security scanner is configured. Applications and claims can be submitted, but uploaded evidence stays quarantined and cannot be downloaded. Generated application PDFs remain available.</p></div>';
 if(isset($_GET['saved']))echo '<div class="notice notice-success"><p>Record updated.</p></div>';
 $id=absint($_GET['record']??0);if($id){if(get_post_type($id)!=='pelham_application')wp_die('Record not found.',404);try{pa_admin_record($id);}catch(Throwable $e){echo '<div class="notice notice-error"><p>Cannot unlock this record. Check the application encryption key and restore it from a secure backup if it changed.</p></div>';}echo '</div>';return;}
 echo '<details class="pa-admin-tools"><summary>Administrator tools · test requests</summary>'.pa_test_controls().'</details>'.pa_test_link_panel();
 $status=sanitize_key($_GET['status']??'');$kind=sanitize_key($_GET['kind']??'');$meta=[];if($status)$meta[]=['key'=>'_pa_status','value'=>$status];if($kind)$meta[]=['key'=>'_pa_kind','value'=>$kind];
 echo '<form class="pa-filters" method="get"><input type="hidden" name="page" value="pelham-applications"><input name="s" aria-label="Search company or reference" placeholder="Search company or reference" value="'.esc_attr(sanitize_text_field($_GET['s']??'')).'"><select name="status" aria-label="Filter by status"><option value="">All statuses</option>';foreach(pa_statuses() as $key=>$label)echo '<option value="'.esc_attr($key).'" '.selected($status,$key,false).'>'.esc_html($label).'</option>';echo '</select><select name="kind" aria-label="Filter by request type"><option value="">All forms</option>';foreach(pa_kinds()+['application'=>'Combined application (before 1.4)'] as $value=>$label)echo '<option value="'.esc_attr($value).'" '.selected($kind,$value,false).'>'.esc_html($label).'</option>';echo '</select><button class="button">Filter</button></form>';
 $paged=max(1,absint($_GET['paged']??1));$q=new WP_Query(['post_type'=>'pelham_application','post_status'=>'private','posts_per_page'=>20,'paged'=>$paged,'s'=>sanitize_text_field($_GET['s']??''),'meta_query'=>$meta]);
 echo '<table class="widefat striped"><caption class="screen-reader-text">Applications and claims</caption><thead><tr><th>Reference / company</th><th>Type</th><th>Status</th><th>Updated</th></tr></thead><tbody>';
 foreach($q->posts as $post){try{$row=pa_get($post->ID);$company=$row['data']['company']??$row['data']['contact_name']??'';}catch(Throwable $e){$row=[];$company='Record unavailable';}$state=get_post_meta($post->ID,'_pa_status',true);echo '<tr><td><a class="pa-row-title" href="'.esc_url(admin_url('admin.php?page=pelham-applications&record='.$post->ID)).'">'.esc_html($company?:'Company details not entered').'</a><small>'.esc_html(pa_reference($post->ID)).'</small></td><td>'.esc_html(pa_kind_label($row['kind']??'application').(($row['kind']??'')==='application'?' (combined)':'')).'</td><td>'.pa_admin_badge($state).'</td><td>'.esc_html(get_date_from_gmt($post->post_modified_gmt,'M j, Y · g:i a')).'</td></tr>';}
 if(!$q->posts)echo '<tr><td colspan="4">No requests found.</td></tr>';echo '</tbody></table>';echo wp_kses_post((string)paginate_links(['base'=>add_query_arg('paged','%#%'),'format'=>'','current'=>$paged,'total'=>$q->max_num_pages]));
 if(current_user_can('manage_options')){ $settings=get_option('pa_settings',[]);echo '<details class="pa-admin-panel pa-settings"><summary>Settings · email and retention</summary><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="pa_settings">';wp_nonce_field('pa_settings');echo '<p><label>Sales notification email <input type="email" required name="sales_email" value="'.esc_attr(pa_sales_email()).'"></label></p><p><label>Delete inactive, unsubmitted drafts after <input type="number" min="7" max="365" required name="draft_days" value="'.esc_attr($settings['draft_days']??30).'"> days</label></p><p>Use a configured SMTP/API mail transport. “Accepted” below means WordPress handed a message to its mail transport; it does not prove inbox delivery.</p><p>Private records use authenticated encryption. Keep the WordPress authentication salts (or a dedicated PELHAM_APPLICATIONS_KEY constant) in your secure backup. Changing the key without migrating records makes existing records unreadable.</p>';submit_button('Save settings');echo '</form></details>';}
 echo '</div>';
}
function pa_statuses(){return ['draft'=>'Draft','received'=>'Received','in_review'=>'In review','needs_information'=>'Needs information','contacted'=>'Contacted','approved'=>'Approved','rejected'=>'Rejected'];}
function pa_admin_record($id){
 $p=pa_get($id);if(!empty($p['test']))echo '<div class="notice notice-warning"><p>TEST RECORD — fictitious data only. No emails are sent.</p></div>';$internal=pa_get($id,'_pa_internal');$revision=(int)get_post_meta($id,'_pa_revision',true);$status=get_post_meta($id,'_pa_status',true);
 echo '<p><a href="'.esc_url(admin_url('admin.php?page=pelham-applications')).'">← All requests</a></p><h2>'.esc_html(($p['data']['company']??$p['data']['contact_name']??'')?:pa_reference($id)).'</h2><p>'.esc_html(pa_reference($id)).' · '.pa_admin_badge($status).' · Submitted revision: '.$revision.'</p>';
 if($revision){echo '<p>';for($r=1;$r<=$revision;$r++)echo '<a class="button" href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=pa_download&record='.$id.'&format=pdf&revision='.$r),'pa_download_'.$id)).'">Download signed PDF · revision '.$r.'</a> ';echo '</p>';}
 pa_admin_documents($id,$p,$revision);
 pa_admin_evidence($id,$p);
 if($revision){
 echo '<form class="pa-admin-panel" method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="pa_review"><input type="hidden" name="record" value="'.$id.'">';wp_nonce_field('pa_review_'.$id);
 echo '<h3>Sales review</h3><p><label>Status <select name="status">';foreach(pa_statuses() as $key=>$label){if($key==='draft')continue;echo '<option value="'.$key.'" '.selected($status,$key,false).'>'.esc_html($label).'</option>';}echo '</select></label></p><p><label>Assigned reviewer ';wp_dropdown_users(['name'=>'owner','selected'=>$internal['owner']??get_current_user_id(),'capability'=>'pelham_review_applications','show_option_none'=>'Unassigned']);echo '</label></p><p><label>Next call <input type="datetime-local" name="next_call" value="'.esc_attr($internal['next_call']??'').'"></label> (WordPress site timezone)</p><p><label>Internal notes<textarea name="notes" rows="4">'.esc_textarea($internal['notes']??'').'</textarea></label></p><p><label>Information to request from customer<textarea name="correction" rows="3">'.esc_textarea($p['correction']??'').'</textarea></label></p><p>This message is emailed when you choose “Needs information”. The customer can resume their saved answers and sign the revised documents.</p>';
 // Credit decision on the Credit Application; platform access on the Customer Application; countersignature on the Terms and Agreements.
 $credit_section=in_array($p['kind'],['application','credit'],true);$portal_section=in_array($p['kind'],['application','customer'],true);
 if($credit_section||$portal_section){
  echo '<h3>'.($credit_section&&$portal_section?'Credit and platform access':($credit_section?'Credit decision':'Platform access')).'</h3>';
  if($credit_section){echo '<p><label>Credit decision <select name="credit_status">';foreach(['not_requested','pending','approved','declined'] as $value)echo '<option '.selected($internal['credit_status']??($p['kind']==='credit'?'pending':'not_requested'),$value,false).' value="'.$value.'">'.esc_html(ucwords(str_replace('_',' ',$value))).'</option>';echo '</select></label> <label>Approved credit limit (USD) <input type="number" min="0" step="0.01" name="credit_limit" value="'.esc_attr($internal['credit_limit']??'').'"></label></p>';}
  if($portal_section){echo '<p><label>Supply Vision customer ID <input name="portal_id" value="'.esc_attr($internal['portal_id']??'').'"></label> <label>Portal status <select name="portal_status">';foreach(['not_created','pending','active','disabled'] as $value)echo '<option '.selected($internal['portal_status']??'not_created',$value,false).' value="'.$value.'">'.esc_html(str_replace('_',' ',$value)).'</option>';echo '</select></label></p><p>These fields record work performed in Supply Vision. They do not provision an external account.</p>';}
 }
 if(in_array($p['kind'],['application','terms'],true)){
  echo '<h3>Pelham representative countersignature</h3><p>The signature applies to the current submitted transport terms and revision. It does not replace the customer signatures.</p><p><label>Representative name <input name="representative" value="'.esc_attr($internal['representative']??'').'"></label> <label>Title <input name="representative_title" value="'.esc_attr($internal['representative_title']??'').'"></label></p>';
  if(!empty($internal['signature']))echo '<p>Signed for revision '.(int)$internal['signed_revision'].' on '.esc_html($internal['signed_at']).'</p><img class="pa-sign-preview" src="'.esc_attr('data:'.$internal['signature']['mime'].';base64,'.$internal['signature']['base64']).'" alt="Pelham representative signature">';
  echo '<div class="pa-admin-sign"><canvas width="1000" height="280" aria-label="Draw representative signature"></canvas><p><button type="button" class="button pa-admin-clear">Clear drawing</button> <label>Or upload signature <input type="file" accept=".png,.jpg,.jpeg,.webp" class="pa-admin-upload"></label></p><input type="hidden" name="representative_signature"><label><input type="checkbox" name="representative_confirm" value="1"> I am authorized to sign these transport terms for Pelham.</label></div>';
 }
 echo '<p><label><input type="checkbox" name="notify" value="1"> Email the customer a status update (only when the status changes)</label></p>';submit_button('Save review');echo '</form>';
 }else{echo '<section class="pa-admin-panel"><h2>Waiting for submission</h2><p>This draft is saved but has not been sent for sales review. You can inspect each document and export a marked draft above.</p></section>';}
 echo '<section class="pa-admin-panel"><h3>Notifications</h3><p>Accepted means handed to the configured mail transport, not confirmed inbox delivery.</p>';foreach(pa_jobs($id) as $key=>$job)echo '<p>'.esc_html($job['subject'].' — '.$job['status'].' — attempts: '.$job['attempts']).'</p>';echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="pa_retry"><input type="hidden" name="record" value="'.$id.'">';wp_nonce_field('pa_retry_'.$id);submit_button('Retry failed notifications','secondary');echo '</form></section><details class="pa-admin-panel"><summary>Audit trail</summary><ul>';foreach(get_post_meta($id,'_pa_audit',true)?:[] as $row)echo '<li>'.esc_html($row['at'].' · user '.$row['user'].' · '.$row['event']).'</li>';echo '</ul></details>';
}
add_action('admin_post_pa_settings',function(){if(!current_user_can('manage_options'))wp_die('Not authorized.',403);check_admin_referer('pa_settings');$email=sanitize_email(wp_unslash($_POST['sales_email']??''));if(!is_email($email))wp_die('Enter a valid sales email.');update_option('pa_settings',['sales_email'=>$email,'draft_days'=>max(7,min(365,absint($_POST['draft_days']??30)))],false);wp_safe_redirect(admin_url('admin.php?page=pelham-applications&saved=1'));exit;});
add_action('admin_post_pa_review',function(){
 if(!pa_can_review())wp_die('Not authorized.',403);$id=absint($_POST['record']??0);check_admin_referer('pa_review_'.$id);if(get_post_type($id)!=='pelham_application')wp_die('Not found.',404);if(!pa_lock($id))wp_die('Record is being updated. Retry in a moment.',409);
 try{
  $p=pa_get($id);$previous=get_post_meta($id,'_pa_status',true);$status=sanitize_key($_POST['status']??'');$revision=(int)get_post_meta($id,'_pa_revision',true);if(!$revision||!isset(pa_statuses()[$status])||$status==='draft')wp_die('Only submitted records can be reviewed.');
  $internal=pa_get($id,'_pa_internal');$internal['owner']=absint($_POST['owner']??0);if($internal['owner']&&!user_can($internal['owner'],'pelham_review_applications'))wp_die('Choose an authorized reviewer.');
  foreach(['next_call','notes','credit_limit','portal_id'] as $key)$internal[$key]=sanitize_textarea_field(wp_unslash($_POST[$key]??''));
  foreach(['credit_status'=>['not_requested','pending','approved','declined'],'portal_status'=>['not_created','pending','active','disabled']] as $key=>$allowed){$v=sanitize_key($_POST[$key]??'');$internal[$key]=in_array($v,$allowed,true)?$v:$allowed[0];}
  $signature=wp_unslash($_POST['representative_signature']??'');if($signature){$image=pa_image($signature);$name=sanitize_text_field(wp_unslash($_POST['representative']??''));$title=sanitize_text_field(wp_unslash($_POST['representative_title']??''));if(!$image||!$name||!$title||empty($_POST['representative_confirm']))wp_die('Provide representative name, title, signature and confirmation.');$internal['signature']=$image;$internal['representative']=$name;$internal['representative_title']=$title;$internal['signed_revision']=$revision;$internal['signed_at']=gmdate('c');$internal['document_sha256']=$p['documents']['terms']['sha256'];$internal['signed_by']=get_current_user_id();$history=pa_get($id,'_pa_countersign_history_'.$revision);$history[]=$internal;pa_put($id,$history,'_pa_countersign_history_'.$revision);pa_put($id,$internal,'_pa_countersign_'.$revision);}
  if($status==='needs_information'){
   $correction=sanitize_textarea_field(wp_unslash($_POST['correction']??''));if(!$correction)wp_die('Describe what the customer needs to correct.');$p['correction']=$correction;$p['signatures']=[];pa_put($id,$p);
   $token=bin2hex(random_bytes(32));update_post_meta($id,'_pa_resume_hash',pa_secret_hash($token));update_post_meta($id,'_pa_resume_expires',time()+30*MINUTE_IN_SECONDS);
   $lang=pa_request_lang($id);$url=pa_page_url($p['kind'],$lang);pa_queue($id,'correction-'.bin2hex(random_bytes(5)),$p['email'],sprintf(pa_t_for('Pelham — information requested %s',$lang),pa_reference($id)),$correction."\n\n".pa_t_for('Open your saved request:',$lang)."\n".$url.'#application-token='.$id.'.'.$token."\n\n".sprintf(pa_t_for('This link expires in 30 minutes. You can request a new link at %s',$lang),$url));
  }elseif(!empty($_POST['notify'])&&$previous!==$status){$lang=pa_request_lang($id);pa_queue($id,'status-'.bin2hex(random_bytes(5)),$p['email'],sprintf(pa_t_for('Pelham — request update %s',$lang),pa_reference($id)),strtr(pa_t_for('Your request %1 is now marked: %2. Contact our team for details. This message does not grant portal access or change your agreed credit terms.',$lang),['%1'=>pa_reference($id),'%2'=>pa_t_for(pa_statuses()[$status],$lang)]));}
  $internal['reviewed_by']=get_current_user_id();$internal['reviewed_at']=gmdate('c');pa_put($id,$internal,'_pa_internal');update_post_meta($id,'_pa_status',$status);pa_audit($id,'Review saved; status '.$status);
 }finally{pa_unlock($id);}wp_safe_redirect(admin_url('admin.php?page=pelham-applications&record='.$id.'&saved=1'));exit;
});
add_action('admin_post_pa_retry',function(){if(!pa_can_review())wp_die('Not authorized.',403);$id=absint($_POST['record']??0);check_admin_referer('pa_retry_'.$id);foreach(pa_jobs($id) as $key=>$job)if($job['status']==='failed'){$job['attempts']=0;$job['status']='pending';update_option(pa_job_option($id,$key),pa_encrypt($job),false);wp_schedule_single_event(time()+1,'pa_send_mail',[$id,$key]);}wp_safe_redirect(admin_url('admin.php?page=pelham-applications&record='.$id));exit;});
